}
function glassPhoto(string $key):string {return '/assets/photos/'.(['web'=>'web','programming'=>'programming','database'=>'database'][$key]??'library').'.jpg';}
function courseMedia(array $course):array {
    static $catalog;
    $catalog ??= require __DIR__.'/course_media.php';
    $key=(string)($course['cover_key']??'default');
    if($uploaded=mediaUrl('course',(int)($course['id']??0),$course['image_path']??null))return ['src'=>$uploaded,'position'=>'50% 50%','label'=>t('Ảnh khóa học')];
    $selected=$catalog[(string)($course['title']??'')]??null;
    if($selected && $selected['theme']===$key) return ['src'=>'/assets/photos/'.$selected['file'],'position'=>$selected['position'],'label'=>$selected['label']];
    return ['src'=>glassPhoto($key),'position'=>'50% 50%','label'=>['web'=>'HTML & CSS','programming'=>'JavaScript','database'=>t('SQL & Dữ liệu')][$key]??'StudyMate'];
}
function cover(string $key,?array $course=null):void {
    $media=courseMedia($course??['cover_key'=>$key]);
    ?><div class="cover photo-cover <?=h($key)?>"><img src="<?=h($media['src'])?>" alt="" loading="lazy" width="720" height="420" style="object-position:<?=h($media['position'])?>"><span class="photo-cover-label"><?=h(t($media['label']))?></span></div><?php
}
function glassCourseMeta(int $courseId):array {
    static $meta;
    if($meta===null){$meta=[];foreach(all('SELECT ch.course_id,COUNT(DISTINCT ch.id) chapters,COUNT(l.id) lessons FROM chapters ch LEFT JOIN lessons l ON l.chapter_id=ch.id GROUP BY ch.course_id') as $row)$meta[(int)$row['course_id']]=$row;}
    return $meta[$courseId]??['chapters'=>0,'lessons'=>0];
}
function courseCard(array $c,?array $e=null):void {
    $meta=glassCourseMeta((int)$c['id']);
    ?><article class="course-card"><a href="<?=h(url($e?'learn':'detail',['id'=>$c['id']]))?>">
        <?php cover($c['cover_key'],$c); ?>
        <div class="card-content"><div class="course-card-top"><span class="course-category"><?=h($c['category_name'])?></span><span class="course-free"><?=h(t('Miễn phí'))?></span></div>
        <h3><?=h($c['title'])?></h3><p class="muted clamp"><?=h($c['description'])?></p>
        <?php if($e):$progress=isset($e['total'])?rowProgress($e):progressFor((int)$e['user_id'],(int)$c['id']); ?><div class="card-progress"><?php progressBar($progress); ?></div><p class="small muted"><?=$e['completed_at']?t('Đã hoàn thành khóa học'):($progress['percent']==100?t('Đã học đủ bài · tiếp tục quiz'):t('Đang học'))?><?=$progress['best']!==null?t(' · Điểm tốt nhất ').h($progress['best']).'%':''?></p><?php endif; ?>
        <div class="course-card-info"><span><?=glassIcon('book')?> <?=(int)$meta['lessons']?> <?=h(t('bài học'))?></span><span><?=glassIcon('grid')?> <?=(int)$meta['chapters']?> <?=h(t('chương'))?></span></div>
        <div class="card-meta"><?php courseInstructorAvatar((int)$c['instructor_id']);?><span><?=h($c['instructor_name'])?><small><?=h(t('Giảng viên'))?></small></span><span class="card-action"><?=$e?t('Tiếp tục học'):t('Xem chi tiết')?></span></div>
        </div></a></article><?php
}
function glassTopics():array {return all("SELECT g.*,COUNT(c.id) total FROM categories g LEFT JOIN courses c ON c.category_id=g.id AND c.status='published' GROUP BY g.id,g.name ORDER BY g.name");}
function glassKicker(string $text):void {echo '<p class="eyebrow">'.h($text).'</p>';}
