function renderMetricBars(array $rows,string $unit):void {
    if(!$rows){echo '<p class="muted">'.h(t('Chưa có dữ liệu để hiển thị.')).'</p>';return;}
    $max=max([1,...array_map(fn($r)=>(float)$r['value'],$rows)]);
    echo '<div class="metric-bars">';foreach($rows as $i=>$row):$value=(float)$row['value'];$width=max(0,min(100,$value/$max*100));?><div class="metric-bar-row"><div><span><?=h($row['label'])?></span><strong><?=h($value)?> <small><?=h(countedLabel($unit,$value))?></small></strong></div><div class="metric-track"><span class="metric-fill color-<?=$i%3?>" style="width:<?=$width?>%"></span></div></div><?php endforeach;echo '</div>';
}
function renderStudyActivity(int $userId):void {
    $zone=new DateTimeZone('Asia/Ho_Chi_Minh');$today=new DateTimeImmutable('today',$zone);$start=$today->modify('-6 days');$utc=$start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$days=[];
    for($i=0;$i<7;$i++){$date=$start->modify('+'.$i.' days');$days[$date->format('Y-m-d')]=['date'=>$date->format('d/m'),'lessons'=>0,'quizzes'=>0];}
    foreach(['lessons'=>['lesson_progress','completed_at'],'quizzes'=>['quiz_attempts','submitted_at']] as $type=>[$table,$column])foreach(all('SELECT '.$column.' stamp FROM '.$table.' WHERE user_id=? AND '.$column.'>=?',[$userId,$utc]) as $row){$key=(new DateTimeImmutable($row['stamp'],new DateTimeZone('UTC')))->setTimezone($zone)->format('Y-m-d');if(isset($days[$key]))$days[$key][$type]++;}
    $max=1;$total=0;foreach($days as $day){$max=max($max,$day['lessons'],$day['quizzes']);$total+=$day['lessons'];}
    ?><section class="insight-panel"><div class="chart-heading"><div><p class="eyebrow"><?=h(t('NHỊP HỌC CỦA BẠN'))?></p><h2><?=h(t('Hoạt động 7 ngày'))?></h2></div><span class="metric-badge"><?=$total?> <?=h(countedLabel('bài đã học',$total))?></span></div><div class="activity-chart" role="img" aria-label="<?=h(t('Số bài hoàn thành và lần nộp quiz trong 7 ngày, có bảng dữ liệu bên dưới'))?>"><?php foreach($days as $key=>$day):?><div class="activity-day"><div class="activity-columns"><span class="lesson-column" style="height:<?=max(2,$day['lessons']/$max*100)?>%" title="<?=h($day['date'])?>: <?=$day['lessons']?> <?=h(t('bài học'))?>"><span><?=$day['lessons']?></span></span><span class="quiz-column" style="height:<?=max(2,$day['quizzes']/$max*100)?>%" title="<?=h($day['date'])?>: <?=$day['quizzes']?> <?=h(t('lần nộp quiz'))?>"><span><?=$day['quizzes']?></span></span></div><small class="<?=$key===$today->format('Y-m-d')?'today':''?>"><?=$day['date']?></small></div><?php endforeach;?></div><div class="chart-legend"><span><i class="lesson-key"></i><?=h(t('Bài hoàn thành'))?></span><span><i class="quiz-key"></i><?=h(t('Lần nộp quiz'))?></span></div><details class="chart-data"><summary><?=h(t('Xem dữ liệu biểu đồ'))?></summary><table class="table"><thead><tr><th><?=h(t('Ngày'))?></th><th><?=h(t('Bài học'))?></th><th><?=h(t('Quiz'))?></th></tr></thead><tbody><?php foreach($days as $day):?><tr><td><?=$day['date']?></td><td><?=$day['lessons']?></td><td><?=$day['quizzes']?></td></tr><?php endforeach;?></tbody></table></details><p class="chart-footnote"><?=h(t('Ngày theo giờ Việt Nam. Hoạt động được ghi từ thao tác trong tài khoản.'))?></p></section><?php
}
function renderScoreChart(int $userId):void {
    $attempts=array_reverse(all('SELECT a.score_percent,a.submitted_at,c.title FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id JOIN courses c ON c.id=q.course_id WHERE a.user_id=? ORDER BY a.submitted_at DESC,a.id DESC LIMIT 6',[$userId]));
    ?><section class="insight-panel"><div class="chart-heading"><div><p class="eyebrow"><?=h(t('LUYỆN TẬP & ÔN TẬP'))?></p><h2><?=h(t('Điểm quiz gần đây'))?></h2></div><span class="metric-badge"><?=count($attempts)?> <?=h(countedLabel('lần nộp',count($attempts)))?></span></div><?php if(!$attempts):?><div class="chart-empty"><?=glassIcon('chart')?><h3><?=h(t('Chưa có kết quả quiz'))?></h3><p><?=h(t('Hoàn thành bài học rồi thử quiz để bắt đầu theo dõi kết quả.'))?></p></div><?php else:$points=[];foreach($attempts as $i=>$a){$x=count($attempts)===1?270:54+$i/(count($attempts)-1)*440;$y=190-(float)$a['score_percent']*1.55;$points[]=[$x,$y];}?><svg class="score-chart" viewBox="0 0 550 230" role="img" aria-label="<?=h(t('Điểm phần trăm của tối đa sáu lần nộp quiz gần nhất'))?>"><?php foreach([0,50,100] as $tick):$y=190-$tick*1.55;?><line class="chart-gridline" x1="48" y1="<?=$y?>" x2="510" y2="<?=$y?>"/><text class="chart-axis" x="10" y="<?=$y+5?>"><?=$tick?>%</text><?php endforeach;?><line class="passing-line" x1="48" y1="81.5" x2="510" y2="81.5"/><polyline class="score-line" points="<?=h(implode(' ',array_map(fn($p)=>$p[0].','.$p[1],$points)))?>"/><?php foreach($points as $i=>[$x,$y]):?><g tabindex="0"><title><?=h($attempts[$i]['title'])?>: <?=h($attempts[$i]['score_percent'])?>%</title><circle class="score-dot" cx="<?=$x?>" cy="<?=$y?>" r="5"/><text class="score-value" x="<?=$x?>" y="<?=$y-13?>" text-anchor="middle"><?=h($attempts[$i]['score_percent'])?>%</text><text class="chart-axis" x="<?=$x?>" y="220" text-anchor="middle"><?=h(t('Lần'))?> <?=$i+1?></text></g><?php endforeach;?></svg><div class="chart-legend"><span><i class="lesson-key"></i><?=h(t('Điểm mỗi lần nộp'))?></span><span class="passing-label"><?=h(t('Ngưỡng hoàn thành 70%'))?></span></div><details class="chart-data"><summary><?=h(t('Xem từng kết quả'))?></summary><ol><?php foreach($attempts as $a):?><li><?=h($a['title'])?> · <?=h($a['score_percent'])?>%</li><?php endforeach;?></ol></details><?php endif;?></section><?php
}
function pageStudent():void {
    $u=requireUser('student');$q=searchQuery();$where="e.user_id=? AND c.title LIKE ? ESCAPE '!'";$params=[$u['id'],searchPattern($q)];
    $list=pageQuery('SELECT COUNT(*) FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE '.$where,'SELECT c.*,g.name category_name,u.name instructor_name,e.user_id,e.completed_at,COALESCE(totals.total,0) total,COALESCE(done.done,0) done,scores.best FROM enrollments e JOIN courses c ON c.id=e.course_id JOIN categories g ON g.id=c.category_id JOIN users u ON u.id=c.instructor_id '.progressJoins().' WHERE '.$where.' ORDER BY e.created_at DESC,e.id DESC',$params);
    $stats=one('SELECT COUNT(*) total,SUM(CASE WHEN completed_at IS NOT NULL THEN 1 ELSE 0 END) completed FROM enrollments WHERE user_id=?',[$u['id']]);$overall=one('SELECT COALESCE(SUM(totals.total),0) total,COALESCE(SUM(done.done),0) done FROM enrollments e '.progressJoins().' WHERE e.user_id=?',[$u['id']]);
    ?><main class="container student-workspace glass-dashboard"><aside class="workspace-nav glass-surface"><p class="workspace-overline"><?=h(t('KHÔNG GIAN CÁ NHÂN'))?></p><p class="workspace-person"><span class="profile-monogram">SM</span><?=h($u['name'])?><small><?=h(t('Học theo cách của bạn'))?></small></p><nav aria-label="<?=h(t('Không gian học tập'))?>"><a class="active" href="<?=h(url('student'))?>" aria-current="page"><?=glassIcon('grid')?> <?=h(t('Tổng quan học tập'))?></a><a href="#my-courses-title"><?=glassIcon('book')?> <?=h(t('Khóa học của tôi'))?></a><a href="<?=h(url('courses'))?>"><?=glassIcon('search')?> <?=h(t('Khám phá khóa học'))?></a><a href="<?=h(url('profile'))?>"><?=glassIcon('user')?> <?=h(t('Hồ sơ cá nhân'))?></a></nav><div class="sidebar-note"><?=glassIcon('shield')?><p><?=h(t('Mỗi bước nhỏ đều có ý nghĩa.'))?><small><?=h(t('Hoàn thành bài, luyện tập và quay lại khi bạn sẵn sàng.'))?></small></p></div></aside><div class="workspace-main"><header class="dashboard-heading"><div><p class="eyebrow"><?=h(t('HÀNH TRÌNH CỦA BẠN'))?></p><h1><?=h(t('Chào'))?> <?=h($u['name'])?>,<br><?=h(t('hôm nay mình học gì?'))?></h1><p class="muted"><?=h(t('Một góc nhìn rõ hơn về những điều bạn đang học.'))?></p></div><span class="dashboard-date"><?=glassIcon('clock')?> <?=h((new DateTimeImmutable('now',new DateTimeZone('Asia/Ho_Chi_Minh')))->format('d / m / Y'))?></span></header><div class="dashboard-stat-grid"><div class="dashboard-stat"><span><?=glassIcon('book')?></span><p><?=h(t('Khóa đang tham gia'))?><strong><?=(int)$stats['total']?></strong></p></div><div class="dashboard-stat"><span><?=glassIcon('check')?></span><p><?=h(t('Khóa đã hoàn thành'))?><strong><?=(int)($stats['completed']??0)?></strong></p></div><div class="dashboard-stat"><span><?=glassIcon('chart')?></span><p><?=h(t('Bài đã học'))?><strong><?=(int)$overall['done']?><small>/ <?=(int)$overall['total']?></small></strong></p></div></div><div class="analytics-grid"><?php renderStudyActivity((int)$u['id']);renderScoreChart((int)$u['id']);?></div><section class="my-learning"><div class="section-top"><div><p class="eyebrow"><?=h(t('TIẾP TỤC TỪ NƠI ĐÃ DỪNG'))?></p><h2 id="my-courses-title"><?=h(t('Khóa học của tôi'))?></h2></div><a class="text-link" href="<?=h(url('courses'))?>"><?=h(t('Tìm khóa học mới'))?></a></div><form class="filter-bar" method="get"><?=hidden('page','student')?><?php field('q',t('Tìm khóa đã tham gia'),$q,'text','maxlength="100"');?><button class="btn btn-primary"><?=h(t('Tìm'))?></button></form><div class="course-grid"><?php foreach($list['rows'] as $e)courseCard($e,$e);?></div><?php if(!$list['rows'])emptyState(t('Không có khóa học phù hợp'),t('Thử tên khác hoặc tham gia một khóa học từ thư viện.'));pagination($list);?></section></div></main><?php
}
function renderInstructorInsights(int $userId):void {
    $rows=all('SELECT c.title,COUNT(e.id) total FROM courses c LEFT JOIN enrollments e ON e.course_id=c.id WHERE c.instructor_id=? GROUP BY c.id,c.title ORDER BY total DESC,c.id DESC LIMIT 5',[$userId]);$quiz=one('SELECT COUNT(a.id) total,COALESCE(SUM(a.passed),0) passed FROM quiz_attempts a JOIN quizzes q ON q.id=a.quiz_id JOIN courses c ON c.id=q.course_id WHERE c.instructor_id=?',[$userId]);
    ?><div class="analytics-grid management-insights"><section class="insight-panel"><div class="chart-heading"><div><p class="eyebrow"><?=h(t('KHÓA HỌC CỦA BẠN'))?></p><h2><?=h(t('Lượt đăng ký theo khóa'))?></h2></div><?=glassIcon('chart')?></div><?php renderMetricBars(array_map(fn($r)=>['label'=>$r['title'],'value'=>(int)$r['total']],$rows),t('lượt'));?><p class="chart-footnote"><?=h(t('Tối đa 5 khóa có nhiều đăng ký nhất. Một người có thể tham gia nhiều khóa.'))?></p></section><section class="insight-panel"><div class="chart-heading"><div><p class="eyebrow"><?=h(t('KẾT QUẢ LUYỆN TẬP'))?></p><h2><?=h(t('Tỷ lệ lần nộp đạt'))?></h2></div></div><?php renderPassRing((int)$quiz['passed'],(int)$quiz['total']);?><p class="chart-footnote"><?=h(t('Tính theo lần nộp quiz, không phải số học viên duy nhất.'))?></p></section></div><?php
}
function renderPassRing(int $passed,int $total):void {
    $percent=$total?round($passed/$total*100):0;$length=2*pi()*48;
    ?><div class="pass-ring"><svg viewBox="0 0 120 120" role="img" aria-label="<?=$passed?> <?=h(t('trên'))?> <?=$total?> <?=h(t('lần nộp đạt'))?>"><circle class="ring-track" cx="60" cy="60" r="48"/><circle class="ring-value" cx="60" cy="60" r="48" stroke-dasharray="<?=$length*$percent/100?> <?=$length?>"/><text x="60" y="64" text-anchor="middle"><?=$percent?>%</text></svg><div><strong><?=$passed?> / <?=$total?></strong><p><?=h(t('lần nộp đạt từ 70%'))?></p><?php if(!$total):?><small><?=h(t('Chưa có dữ liệu quiz.'))?></small><?php endif;?></div></div><?php
}
function renderAdminInsights():void {
    $roles=all('SELECT role,COUNT(*) total FROM users GROUP BY role');$names=['student'=>t('Học viên'),'instructor'=>t('Giảng viên'),'admin'=>t('Quản trị viên')];$quiz=one('SELECT COUNT(*) total,COALESCE(SUM(passed),0) passed FROM quiz_attempts');
    ?><div class="analytics-grid management-insights"><section class="insight-panel"><div class="chart-heading"><div><p class="eyebrow"><?=h(t('TÀI KHOẢN TRONG HỆ THỐNG'))?></p><h2><?=h(t('Phân bố vai trò'))?></h2></div><?=glassIcon('user')?></div><?php renderMetricBars(array_map(fn($r)=>['label'=>$names[$r['role']]??$r['role'],'value'=>(int)$r['total']],$roles),t('tài khoản'));?><p class="chart-footnote"><?=h(t('Bao gồm tài khoản đang hoạt động và đã khóa.'))?></p></section><section class="insight-panel"><div class="chart-heading"><div><p class="eyebrow"><?=h(t('TỔNG QUAN ÔN TẬP'))?></p><h2><?=h(t('Tỷ lệ lần nộp đạt'))?></h2></div></div><?php renderPassRing((int)$quiz['passed'],(int)$quiz['total']);?></section></div><?php
}
